class Solution:
    def matchPlayersAndTrainers(self, players: list[int], trainers: list[int]) -> int:
        players.sort()
        trainers.sort()
        p, t = 0, 0
        matches = 0
        while p < len(players) and t < len(trainers):
            if players[p] <= trainers[t]:
                matches += 1
                p += 1
            t += 1
        return matches

class Solution {
public:
    int matchPlayersAndTrainers(std::vector<int>& players, std::vector<int>& trainers) {
        std::sort(players.begin(), players.end());
        std::sort(trainers.begin(), trainers.end());
        int p = 0, t = 0, matches = 0;
        while (p < (int)players.size() && t < (int)trainers.size()) {
            if (players[p] <= trainers[t]) {
                matches++;
                p++;
            }
            t++;
        }
        return matches;
    }
};

class Solution {
    public int matchPlayersAndTrainers(int[] players, int[] trainers) {
        java.util.Arrays.sort(players);
        java.util.Arrays.sort(trainers);
        int p = 0, t = 0, matches = 0;
        while (p < players.length && t < trainers.length) {
            if (players[p] <= trainers[t]) {
                matches++;
                p++;
            }
            t++;
        }
        return matches;
    }
}

var matchPlayersAndTrainers = function(players, trainers) {
    players.sort((a, b) => a - b);
    trainers.sort((a, b) => a - b);
    let p = 0, t = 0, matches = 0;
    while (p < players.length && t < trainers.length) {
        if (players[p] <= trainers[t]) {
            matches++;
            p++;
        }
        t++;
    }
    return matches;
};
